#!/usr/bin/env sh
# Reject (or strip) AI co-author / "generated by AI" trailers in a text file.
#
# Usage:
#   guard-no-ai-trailer.sh <file>            # exit 1 if a forbidden line exists
#   guard-no-ai-trailer.sh --strip <file>    # remove forbidden lines in place
#
# Reused by git-commit, git-release and git-pr.
set -eu

STRIP=0
if [ "${1:-}" = "--strip" ]; then STRIP=1; shift; fi
FILE="${1:?usage: guard-no-ai-trailer.sh [--strip] <file>}"
[ -f "$FILE" ] || { echo "guard: no such file: $FILE" >&2; exit 2; }

# Known AI-attribution patterns. Case-insensitive.
PATTERN='co-authored-by:.*(claude|anthropic|openai|chatgpt|gpt|copilot|cursor|gemini|codex|noreply@anthropic)|generated with (claude|copilot|cursor|codex|ai)|🤖 generated'

if [ "$STRIP" -eq 1 ]; then
  grep -ivE "$PATTERN" "$FILE" > "$FILE.guard.tmp" || true
  # drop trailing blank lines
  awk 'NF{last=NR} {line[NR]=$0} END{for(i=1;i<=last;i++) print line[i]}' \
    "$FILE.guard.tmp" > "$FILE"
  rm -f "$FILE.guard.tmp"
  exit 0
fi

if grep -iqE "$PATTERN" "$FILE"; then
  echo "ERROR: AI attribution trailer found in $FILE:" >&2
  grep -inE "$PATTERN" "$FILE" >&2
  echo "Remove these lines (or re-run with --strip) before continuing." >&2
  exit 1
fi
exit 0
